1	/**
2	 * Comment creation, edit window enforcement, mention extraction and soft delete.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, archivePatch, consumeRateLimit
5	 */
6	import { emit } from "@/lib/event-bus";
7	import { resolveMentions } from "@/lib/mentions";
8	import { assertCan } from "@/lib/permissions";
9	import { consumeRateLimit } from "@/lib/rate-limit";
10	import { archivePatch, assertNotArchived } from "@/lib/soft-delete";
11	import { assertOrgScope } from "@/lib/tenant";
12	import * as commentRepo from "@/server/repositories/comment-repository";
13	import * as issueRepo from "@/server/repositories/issue-repository";
14	import * as memberRepo from "@/server/repositories/member-repository";
15	import {
16	  actorEnvelope,
17	  commentResource,
18	  issueResource,
19	  requireFound,
20	} from "./_support";
21	import type {
22	  CreateCommentInput,
23	  DeleteCommentInput,
24	  UpdateCommentInput,
25	} from "@/schemas/comment";
26	import type { Comment, CommentThreadNode } from "@/types/comment";
27	import type { IssueId, OrgId, UserId } from "@/types/common";
28	import type { Actor } from "@/types/member";
29	
30	/** How long after posting an author may still edit their own comment. */
31	const EDIT_WINDOW_MS = 15 * 60 * 1000;
32	
33	/** How many members are scanned when resolving `@handle` mentions. */
34	const MENTION_LOOKUP_LIMIT = 100;
35	
36	/** Token bucket protecting the comment thread from burst posting. */
37	const COMMENT_CREATE_BUCKET = "comment:create";
38	
39	/**
40	 * Posts a comment on a live issue. Mentions written as `@handle` in the body
41	 * are resolved against the org's members here, so the stored row and the
42	 * `comment.created` payload agree on who was mentioned — the notification
43	 * fan-out reads that list rather than re-parsing the markdown.
44	 */
45	export async function createComment(
46	  actor: Actor,
47	  input: CreateCommentInput,
48	): Promise<Comment> {
49	  assertOrgScope(actor, input.orgId);
50	
51	  const issue = requireFound(
52	    await issueRepo.findIssueById(input.orgId, input.issueId),
53	    "Issue",
54	    input.issueId,
55	  );
56	  assertCan(actor, "comment:create", issueResource(issue));
57	  assertNotArchived("Issue", issue.id, issue);
58	
59	  const verdict = await consumeRateLimit(input.orgId, COMMENT_CREATE_BUCKET);
60	  if (!verdict.allowed) {
61	    throw new Error(
62	      `Comment rate limit reached; try again after ${verdict.resetAt}`,
63	    );
64	  }
65	
66	  const mentionedUserIds = await resolveMentionedUsers(
67	    input.orgId,
68	    input.body,
69	    input.mentionedUserIds,
70	  );
71	
72	  const comment = await commentRepo.insertComment(
73	    { ...input, mentionedUserIds: [...mentionedUserIds] },
74	    actor.userId,
75	  );
76	
77	  await emit("comment.created", {
78	    ...actorEnvelope(actor),
79	    commentId: comment.id,
80	    issueId: comment.issueId,
81	    mentionedUserIds,
82	  });
83	
84	  return comment;
85	}
86	
87	/**
88	 * Edits are allowed inside a fifteen-minute window, or by anyone the role
89	 * matrix already lets update a comment. `can()` decides the second half —
90	 * this service only owns the time window.
91	 */
92	export async function updateComment(
93	  actor: Actor,
94	  input: UpdateCommentInput,
95	): Promise<Comment> {
96	  assertOrgScope(actor, input.orgId);
97	
98	  const comment = requireFound(
99	    await commentRepo.findCommentById(input.orgId, input.commentId),
100	    "Comment",
101	    input.commentId,
102	  );
103	  assertCan(actor, "comment:update", commentResource(comment));
104	  assertNotArchived("Comment", comment.id, comment);
105	
106	  if (comment.authorId === actor.userId && isPastEditWindow(comment)) {
107	    throw new Error("The edit window for this comment has closed");
108	  }
109	
110	  return commentRepo.updateComment(input);
111	}
112	
113	/**
114	 * Deletion is soft: the row keeps its place so replies below it still have an
115	 * anchor. `archivePatch()` is what the repository writes; asking for it here
116	 * documents that this service deliberately never issues a hard delete.
117	 */
118	export async function deleteComment(
119	  actor: Actor,
120	  input: DeleteCommentInput,
121	): Promise<Comment> {
122	  assertOrgScope(actor, input.orgId);
123	
124	  const comment = requireFound(
125	    await commentRepo.findCommentById(input.orgId, input.commentId),
126	    "Comment",
127	    input.commentId,
128	  );
129	  assertCan(actor, "comment:delete", commentResource(comment));
130	  assertNotArchived("Comment", comment.id, comment);
131	
132	  const { archivedAt } = archivePatch();
133	  const archived = await commentRepo.archiveComment(
134	    input.orgId,
135	    input.commentId,
136	  );
137	
138	  await emit("comment.deleted", {
139	    ...actorEnvelope(actor),
140	    occurredAt: archivedAt,
141	    commentId: archived.id,
142	    issueId: archived.issueId,
143	  });
144	
145	  return archived;
146	}
147	
148	export async function getThread(
149	  actor: Actor,
150	  orgId: OrgId,
151	  issueId: IssueId,
152	): Promise<readonly CommentThreadNode[]> {
153	  assertOrgScope(actor, orgId);
154	
155	  const issue = requireFound(
156	    await issueRepo.findIssueById(orgId, issueId),
157	    "Issue",
158	    issueId,
159	  );
160	  assertCan(actor, "comment:read", issueResource(issue));
161	
162	  return commentRepo.listThread(orgId, issueId);
163	}
164	
165	function isPastEditWindow(comment: Comment): boolean {
166	  const posted = new Date(comment.createdAt).getTime();
167	  return Date.now() - posted > EDIT_WINDOW_MS;
168	}
169	
170	/**
171	 * Union of the ids the client already resolved (optimistic UI) and the ones
172	 * parsed out of the body server-side. The server list wins on disagreement.
173	 */
174	async function resolveMentionedUsers(
175	  orgId: OrgId,
176	  body: string,
177	  clientProvided: readonly UserId[],
178	): Promise<readonly UserId[]> {
179	  const members = await memberRepo.listMembers({
180	    orgId,
181	    limit: MENTION_LOOKUP_LIMIT,
182	    cursor: null,
183	  });
184	
185	  const resolved = resolveMentions(body, members.items);
186	  const known = new Set(members.items.map((member) => member.userId));
187	
188	  return [
189	    ...new Set([...resolved, ...clientProvided.filter((id) => known.has(id))]),
190	  ];
191	}
